import {createKimiColdWorkerMcpBridge} from '/Users/sun/Code/repos/rah_os/packages/agent-host/src/worker-mcp-bridge.ts';
// Private ordinary-reply prototype. Kernel remains the target and mutation owner.
export function createBoundReplyBridge(input) {
 const {deliveredSeq,fetch:upstream=fetch,...bridge}=input;
 if(!Number.isSafeInteger(deliveredSeq)||deliveredSeq<0) throw Error('Invalid frozen delivered sequence');
 const endpoint=bridge.workerApiOrigin+'/v1/worker/messages/post';
 return createKimiColdWorkerMcpBridge({...bridge,fetch:async(url,init)=>{
  const command=JSON.parse(init.body);
  if(url!==endpoint||Object.keys(command).some(k=>!['body','final','idempotencyKey'].includes(k)))
   return Response.json({error:{code:'INVALID_ARGUMENTS',message:'This reply accepts only body and final; execution context is Host-bound.'}},{status:400});
  return upstream(url,{...init,body:JSON.stringify({...command,basedOnRoomSeq:deliveredSeq})});
 }});
}

