export const parameters={type:'object',properties:{body:{type:'string'},final:{type:'boolean'}},required:['body','final'],additionalProperties:false};
export function projectResult(args,result){
 let receipt;try{if(result.content?.length===1&&result.content[0].type==='text')receipt=JSON.parse(result.content[0].text);}catch{}
 const published=result.isError===false&&receipt?.state==='published'&&typeof receipt.messageId==='string'&&receipt.messageId.length>0&&Number.isSafeInteger(receipt.roomSeq)&&receipt.roomSeq>0;
 return {content:published?[{type:'text',text:'Published.'}]:result.content,isError:result.isError,details:{receipt:result},terminate:published&&args.final===true};
}

