import {parameters,projectResult} from './model.mjs';
export default function(pi){
 pi.registerTool({name:'loom_reply',label:'Loom reply',description:'Send your reply. Use final=true when your answer is complete, or final=false for a progress update.',parameters,
 prepareLoadout(){return {hiddenDeclarations:['mcp__loom_worker__loom_reply']};},
 async execute(id,args,signal,onUpdate,ctx){const output=await ctx.executeTool('mcp__loom_worker__loom_reply',args,{signal});return projectResult(args,{...output.result,isError:output.isError});}
 });
}

