import {appendFileSync} from 'node:fs';
export function decision(input){
 if(input.hook_event_name!=='PostToolUse'||input.tool_name!=='mcp__loom_worker__loom_reply'||input.tool_input?.final!==true)return {};
 const response=input.tool_response;
 const content=Array.isArray(response)?response:response?.content;
 if(!response||response.isError===true||!Array.isArray(content))return {};
 let receipt;
 try {receipt=JSON.parse(content.find(x=>x.type==='text')?.text);}catch{return {};}
 if(receipt?.state!=='published'||typeof receipt.messageId!=='string'||!Number.isInteger(receipt.roomSeq))return {};
 return {continue:false,stopReason:'Loom final reply published; this turn is complete.'};
}
if(process.argv[1]===new URL(import.meta.url).pathname){
 let raw='';for await(const chunk of process.stdin)raw+=chunk;
 const input=JSON.parse(raw);const output=decision(input);
 if(process.env.LOOM_HOOK_AUDIT)appendFileSync(process.env.LOOM_HOOK_AUDIT,JSON.stringify({input,output})+'\n');
 console.log(JSON.stringify(output));
}
